//
// wb_cfg_pipe — posted-write / blocking-read Wishbone pipe.
//
// Write: ACK when the beat is accepted into the queue (not when it retires
// at the leaf). Read: never early-ACK; a read drains prior writes (barrier).
//
// TGA ports are always present. TW is at least 1 (the default): a fabric
// with no tag instantiates TW=1, ties .m_tga to 1'b0, and sinks .s_tga.
// {m_tga, m_adr} is packed into the beat and unpacked at the leaf.
//
// Comb tap (pipe_m / pipe_s) is split from FF array pipe_q so Verilator does
// not X-propagate. Icarus rejects q[i].field: hops use whole-element NBA.

module wb_cfg_pipe #(
	parameter int unsigned PIPE = 1,
	parameter int unsigned AW   = 32,
	parameter int unsigned TW   = 1
) (
	input  logic                  clk,
	input  logic                  rst_n,

	input  logic                  m_cyc,
	input  logic                  m_stb,
	input  logic                  m_we,
	input  logic [AW-1:0]         m_adr,
	input  logic [31:0]           m_dat,
	input  logic [3:0]            m_sel,
	input  logic [TW-1:0]         m_tga,
	output logic                  m_ack,
	output logic [31:0]           m_rdat,

	output logic                  s_cyc,
	output logic                  s_stb,
	output logic                  s_we,
	output logic [AW-1:0]         s_adr,
	output logic [31:0]           s_dat,
	output logic [3:0]            s_sel,
	output logic [TW-1:0]         s_tga,
	input  logic                  s_ack,
	input  logic [31:0]           s_rdat
);

	localparam int unsigned PW = AW + TW;

	typedef struct packed {
		logic          cyc;
		logic          ack;
		logic          stb;
		logic          we;
		logic [PW-1:0] adr;
		logic [3:0]    sel;
		logic [31:0]   wdat;
		logic [31:0]   rdat;
	} beat_t;

	// One struct is reused in both directions, so each tap reads only some fields.
	/* verilator lint_off UNUSEDSIGNAL */
	beat_t pipe_m;
	beat_t pipe_q [1:PIPE];
	beat_t pipe_q1;
	beat_t pipe_s;
	beat_t pipe_h;
	/* verilator lint_on UNUSEDSIGNAL */
	logic [PW-1:0] m_adr_pack;

	assign pipe_q1 = pipe_q[1];
	assign pipe_h  = pipe_q[PIPE];

	assign m_adr_pack = {m_tga, m_adr};
	assign s_adr      = pipe_h.adr[AW-1:0];
	assign s_tga      = pipe_h.adr[AW+TW-1:AW];

	always_comb begin
		pipe_m.cyc  = m_cyc;
		pipe_m.stb  = m_stb;
		pipe_m.we   = m_we;
		pipe_m.adr  = m_adr_pack;
		pipe_m.sel  = m_sel;
		pipe_m.wdat = m_dat;
		pipe_m.ack  = m_cyc & m_stb & (m_we ? !pipe_q1.stb : pipe_q1.ack);
		pipe_m.rdat = pipe_q1.rdat;

		m_ack  = pipe_m.ack;
		m_rdat = pipe_m.rdat;

		pipe_s.cyc  = pipe_h.cyc;
		pipe_s.ack  = pipe_h.stb & s_ack & !pipe_h.we;
		pipe_s.stb  = pipe_h.stb & !s_ack;
		pipe_s.we   = pipe_h.we;
		pipe_s.adr  = pipe_h.adr;
		pipe_s.sel  = pipe_h.sel;
		pipe_s.wdat = pipe_h.wdat;
		pipe_s.rdat = s_rdat;
	end

	assign s_cyc = pipe_h.cyc;
	assign s_stb = pipe_h.stb;
	assign s_we  = pipe_h.we;
	assign s_dat = pipe_h.wdat;
	assign s_sel = pipe_h.sel;

	for (genvar i = 1; i <= PIPE; i++) begin : hop
		// Forward hop reads request fields; return hop reads ack / rdat.
		/* verilator lint_off UNUSEDSIGNAL */
		beat_t prv;
		beat_t nxt;
		/* verilator lint_on UNUSEDSIGNAL */
		if (i == 1) begin : gprv
			assign prv = pipe_m;
		end else begin : gprv
			assign prv = pipe_q[i-1];
		end
		if (i == PIPE) begin : gnxt
			assign nxt = pipe_s;
		end else begin : gnxt
			assign nxt = pipe_q[i+1];
		end
		always_ff @(posedge clk or negedge rst_n) begin
			if (!rst_n) pipe_q[i] <= '0;
			else begin
				beat_t cur, nxtq;
				cur  = pipe_q[i];
				nxtq = cur;
				nxtq.ack  = nxt.ack;
				nxtq.rdat = nxt.rdat;
				if (!cur.stb) begin
					nxtq.cyc = prv.cyc;
					if (prv.stb && (prv.we || !prv.ack) && !cur.ack) begin
						nxtq.stb  = prv.stb;
						nxtq.we   = prv.we;
						nxtq.adr  = prv.adr;
						nxtq.sel  = prv.sel;
						nxtq.wdat = prv.wdat;
					end
				end else if (cur.we && !nxt.stb) begin
					nxtq.cyc  = prv.cyc;
					nxtq.stb  = 1'b0;
					nxtq.we   = 1'b0;
					nxtq.adr  = {PW{1'b0}};
					nxtq.sel  = 4'h0;
					nxtq.wdat = 32'h0;
				end else if (nxt.ack) begin
					nxtq.cyc  = 1'b0;
					nxtq.stb  = 1'b0;
					nxtq.we   = 1'b0;
					nxtq.adr  = {PW{1'b0}};
					nxtq.sel  = 4'h0;
					nxtq.wdat = 32'h0;
				end
				pipe_q[i] <= nxtq;
			end
		end
	end

endmodule
